# backend/api/routes/job_recurrence_rules.py
# B21: CRUD endpoints for job recurrence rules (recurring job series).
#
# Design: Creating a rule immediately creates the FIRST job instance.
# Subsequent jobs are generated by the Celery Beat task in tasks/recurring_jobs.py.

