# ==================== SHARED IMPL FUNCTIONS ====================


def _list_rules_impl(
    skip: int,
    limit: int,
    db: Session,
    tenant_id: UUID,
) -> RecurrenceRuleListResponse:
    rules = db.exec(
        select(JobRecurrenceRule)
        .where(JobRecurrenceRule.tenant_id == tenant_id)
        .offset(skip)
        .limit(limit)
        .order_by(JobRecurrenceRule.next_job_at)
    ).all()

    total = db.exec(
        select(JobRecurrenceRule).where(JobRecurrenceRule.tenant_id == tenant_id)
    ).all()

    items = []
    for rule in rules:
        # Denormalize customer name
        customer = db.exec(
            select(Customer)
            .where(Customer.id == rule.customer_id)
            .where(Customer.tenant_id == tenant_id)
        ).first()

        # Denormalize site address
        site = db.exec(
            select(Site)
            .where(Site.id == rule.site_id)
            .where(Site.tenant_id == tenant_id)
        ).first()

        # Denormalize tech display name (User.first_name + last_name)
        tech_name = None
        if rule.default_tech_user_id:
            tech = db.exec(
                select(User).where(User.id == rule.default_tech_user_id)
            ).first()
            if tech:
                parts = [p for p in [tech.first_name, tech.last_name] if p]
                tech_name = " ".join(parts) if parts else None

        items.append(
            RecurrenceRuleListItem(
                id=rule.id,
                pattern=rule.pattern,
                interval_count=rule.interval_count,
                customer_name=customer.display_name if customer else None,
                site_address=site.name
                if site
                else None,  # Site uses name, not address_line_1
                next_job_at=rule.next_job_at,
                occurrences_created=rule.occurrences_created,
                is_active=rule.is_active,
                default_tech_display_name=tech_name,
            )
        )

    return RecurrenceRuleListResponse(items=items, total=len(total))


def _get_rule_impl(
    rule_id: UUID, db: Session, tenant_id: UUID
) -> RecurrenceRuleResponse:
    rule = db.exec(
        select(JobRecurrenceRule)
        .where(JobRecurrenceRule.id == rule_id)
        .where(JobRecurrenceRule.tenant_id == tenant_id)
    ).first()
    if not rule:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail={
                "type": "https://errors.pilotfortrades.com/not-found",
                "title": "Recurrence rule not found",
                "status": 404,
                "detail": f"Recurrence rule {rule_id} not found in this tenant.",
            },
        )
    return RecurrenceRuleResponse.model_validate(rule)


def _update_rule_impl(
    rule_id: UUID,
    rule_in: RecurrenceRuleUpdate,
    db: Session,
    tenant_id: UUID,
    user_id: UUID | None,
) -> RecurrenceRuleResponse:
    rule = db.exec(
        select(JobRecurrenceRule)
        .where(JobRecurrenceRule.id == rule_id)
        .where(JobRecurrenceRule.tenant_id == tenant_id)
    ).first()
    if not rule:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail={
                "type": "https://errors.pilotfortrades.com/not-found",
                "title": "Recurrence rule not found",
                "status": 404,
                "detail": f"Recurrence rule {rule_id} not found in this tenant.",
            },
        )

    update_data = rule_in.model_dump(exclude_unset=True)
    for field, value in update_data.items():
        setattr(rule, field, value)

    db.add(rule)
    db.commit()
    db.refresh(rule)
    return RecurrenceRuleResponse.model_validate(rule)


def _delete_rule_impl(
    rule_id: UUID,
    db: Session,
    tenant_id: UUID,
    user_id: UUID | None,
) -> None:
    """Soft-delete: sets is_active = False. Idempotent for already-inactive rules."""
    rule = db.exec(
        select(JobRecurrenceRule)
        .where(JobRecurrenceRule.id == rule_id)
        .where(JobRecurrenceRule.tenant_id == tenant_id)
    ).first()
    if not rule:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail={
                "type": "https://errors.pilotfortrades.com/not-found",
                "title": "Recurrence rule not found",
                "status": 404,
                "detail": f"Recurrence rule {rule_id} not found in this tenant.",
            },
        )
    # Idempotent — already inactive is a no-op
    if rule.is_active:
        rule.is_active = False
        db.add(rule)
        db.commit()


# ==================== AUTHENTICATED ENDPOINTS ====================


@router.post(
    "/", response_model=RecurrenceRuleResponse, status_code=status.HTTP_201_CREATED
)
def create_recurrence_rule(
    rule_in: RecurrenceRuleCreate,
    db: Session = Depends(get_db),
    current_user: AuthenticatedUser = Depends(require_permission("jobs.create")),
):
    """Create a new recurring job rule. Immediately creates the first job."""
    set_audit_context_sync(db, user_id=current_user.id)
    return _create_rule_impl(rule_in, db, current_user.tenant_id, current_user.id)


@router.get("/", response_model=RecurrenceRuleListResponse)
def list_recurrence_rules(
    skip: int = Query(default=0, ge=0),
    limit: int = Query(default=50, le=200),
    db: Session = Depends(get_db),
    current_user: AuthenticatedUser = Depends(require_permission("jobs.view")),
):
    """List all recurrence rules for the tenant."""
    return _list_rules_impl(skip, limit, db, current_user.tenant_id)


@router.get("/{rule_id}", response_model=RecurrenceRuleResponse)
def get_recurrence_rule(
    rule_id: UUID,
    db: Session = Depends(get_db),
    current_user: AuthenticatedUser = Depends(require_permission("jobs.view")),
):
    """Get a single recurrence rule."""
    return _get_rule_impl(rule_id, db, current_user.tenant_id)


@router.patch("/{rule_id}", response_model=RecurrenceRuleResponse)
def update_recurrence_rule(
    rule_id: UUID,
    rule_in: RecurrenceRuleUpdate,
    db: Session = Depends(get_db),
    current_user: AuthenticatedUser = Depends(require_permission("jobs.update")),
):
    """Patch a recurrence rule (pause/resume, change end conditions, etc.)."""
    set_audit_context_sync(db, user_id=current_user.id)
    return _update_rule_impl(
        rule_id, rule_in, db, current_user.tenant_id, current_user.id
    )


@router.delete("/{rule_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_recurrence_rule(
    rule_id: UUID,
    db: Session = Depends(get_db),
    current_user: AuthenticatedUser = Depends(require_permission("jobs.update")),
):
    """Soft-delete (deactivate) a recurrence rule. All generated jobs remain intact."""
    set_audit_context_sync(db, user_id=current_user.id)
    _delete_rule_impl(rule_id, db, current_user.tenant_id, current_user.id)
